// Generate one deterministic node:test case per security vector so the suite
// reports a precise, stable count. Source of truth for the vectors below.
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';

const root = fileURLToPath(new URL('..', import.meta.url));
const q = (s) => JSON.stringify(s);

const lines = [
  '// Generated by scripts/write-vector-tests.mjs. Each vector is a separate test.',
  "import test from 'node:test';",
  "import assert from 'node:assert/strict';",
  "import { sanitizeCell, findCsvTriggers, parseSafeCsv, inspectCsv, stringifySafeCsv, isSafeNegativeNumberValue } from '../src/index.mjs';",
  '',
];
const add = (name, body) => lines.push(`test(${q(name)}, () => { ${body} });`);

// 48 direct trigger vectors.
const triggers = ['=', '+', '-', '@', '\t', '|'];
const payloads = [
  '1+1', 'SUM(A1:A9)', 'HYPERLINK("http://example.test","x")',
  'cmd|\'/c calc\'!A0', 'DDE("cmd";"/c calc";"A0")',
  'importXML("http://example.test")', '2*3', 'NOW()',
];
for (const trigger of triggers) {
  for (const payload of payloads) {
    const value = `${trigger}${payload}`;
    add(`prefix-vector ${q(value)}`, `assert.equal(sanitizeCell(${q(value)}), ${q(`'${value}`)})`);
  }
}

// 16 leading-obfuscation vectors.
const obfuscators = [' ', '   ', ' ', ' ', ' ', '﻿', '͏', '؜', '᠎', 'ㅤ', '­', '\u0000', '\u001f', '\u007f', ' ', ' '];
for (const obf of obfuscators) {
  const value = `${obf}=SUM(1)`;
  add(`obfuscation-vector U+${obf.codePointAt(0).toString(16).toUpperCase()}`,
    `assert.equal(sanitizeCell(${q(value)}), ${q(`'${value}`)}); assert.equal(findCsvTriggers(${q(value)})[0].rule, 'obfuscated-trigger')`);
}

// 16 zero-width and bidi vectors.
const invisibles = ['​', '‌', '‍', '‎', '‏', '‪', '‬', '‮', ' ', '⁦', '⁧', '⁨', '⁩', '﻿', '͏', '؜'];
for (const inv of invisibles) {
  const value = `${inv}@cmd`;
  add(`invisible-vector U+${inv.codePointAt(0).toString(16).toUpperCase()}`,
    `assert.equal(sanitizeCell(${q(value)}), ${q(`'${value}`)}); assert.equal(findCsvTriggers(${q(value)})[0].trigger, '@')`);
}

// 18 multiline smuggling vectors.
for (const sep of ['\n', '\r', '\r\n']) {
  for (const payload of ['=1', '+2', '-3', '@4', '|5', '\t=6']) {
    const value = `safe${sep}${payload}`;
    add(`smuggle-vector ${q(value)}`,
      `assert.equal(sanitizeCell(${q(value)}), ${q(`safe${sep}'${payload}`)}); assert.equal(findCsvTriggers(${q(value)})[0].rule, 'embedded-formula')`);
  }
}

// 16 negative-number mode vectors.
for (const value of ['-1', '-0.5', '-.25', '-1e3', '-1E-3', '-123456789', '-0.00001', '-999']) {
  add(`safe-negative ${q(value)}`,
    `assert.equal(sanitizeCell(${q(value)}, {mode:'preserve-numbers'}), ${q(value)}); assert.equal(isSafeNegativeNumberValue(${q(value)}), true)`);
}
for (const value of ['-1+1', '- 1', '-1abc', '-Infinity', '--1', '-1e', '-1;2', '-SUM(1)']) {
  add(`unsafe-negative ${q(value)}`,
    `assert.equal(sanitizeCell(${q(value)}, {mode:'preserve-numbers'}), ${q(`'${value}`)}); assert.equal(isSafeNegativeNumberValue(${q(value)}), false)`);
}

// 18 parse vectors: simple matrix injections.
const matrixPayloads = [
  'name,formula\nAlice,=1\n', 'name,formula\nAlice,+1\n', 'name,formula\nAlice,-1\n',
  'name,formula\nAlice,@1\n', 'name,formula\nAlice,\t=1\n', 'name,formula\nAlice,|=1\n',
  'name,formula\nAlice, =1\n', 'name,formula\nAlice,﻿=1\n', 'name,formula\nAlice,=cmd|calc\n',
  'a,b\n"=1",2\n', 'a,b\n"line1\n=cmd",2\n', '﻿a,b\n=1,2\n',
  'a,b\r\n=1,2\r\n', 'a,b\n=1\n+2\n', 'a,b\n1,2\n=3,4\n',
  'x,y,z\n=1,=2,=3\n', 'a,b\n"=1","=2"\n', 'a,b\n1,2\n\n=3,4\n',
];
for (const [i, input] of matrixPayloads.entries()) {
  add(`parse-matrix-vector ${i}`,
    `const rows = parseSafeCsv(${q(input)}); assert.ok(rows.length >= 1); assert.ok(JSON.stringify(rows).includes("'") || inspectCsv(${q(input)}).safe === false)`);
}

// 12 stringify vectors.
for (const value of ['=1', '+2', '-3', '@4', '\t=5', '|=6', ' =7', '﻿=8', 'ok\n=9', 'ok\r=10', '=cmd|calc', '@SUM(1)']) {
  add(`stringify-vector ${q(value)}`,
    `const out = stringifySafeCsv([[${q(value)}]]); assert.ok(out.startsWith("'") || out.includes("\\n'") || out.includes("\\r'") || out.startsWith("ok\\n'") || out.startsWith("ok\\r'")); assert.equal(inspectCsv(out).safe, true)`);
}

writeFileSync(join(root, 'tests', 'vectors.test.mjs'), `${lines.join('\n')}\n`);
console.log(`Generated ${lines.filter((l) => l.startsWith('test(')).length} vector tests.`);
